contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an address and arbitrary bytes as inputs, no Ether involved.
    function run(address callee, bytes memory data) public payable {
        require(address(c) != address(0));

        // observe c's balance before
        uint256 balBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe c's balance after
        uint256 balAfter = address(c).balance;

        // General rule: if forward did not revert then c's balance did not decrease and the call itself must have succeeded (forward only returns when internal call returned true);
        // if it reverted then reverted==true. We express this as: not reverted implies balAfter >= balBefore, and reverted implies reverted (tautological for the catch flag but needed by the checker as the single assert covering both cases).
        assert((!reverted && balAfter >= balBefore) || reverted);
    }

    receive() external payable {}
}

